/**
 * The Wire Contract's stamping seam (see CONTEXT.md: Wire Contract).
 *
 * Every reviewer agent file carries text that one fragment under
 * references/reviewer-wire/ owns:
 *
 * - `wire-contract.md`, generated by renderReviewerWireContract(), between the
 *   wire-contract markers;
 * - `bootstrap.md` and `before-you-emit.md`, hand-written, between their own
 *   markers;
 * - `read-coverage.md`, one hand-written bullet located by its opening words.
 *
 * The refutation verifier carries one more region, the lens sections of
 * references/review-lenses.md, stamped by the same script.
 *
 * This module owns the pure replacement so the stamp script and the drift
 * tests share one implementation — a test proving regions equal the fragment
 * through a DIFFERENT parser than the stamper writes with would be two
 * contracts again. It also owns which stamps an agent of each kind carries
 * (`stampsFor`) and how a list of them is applied to one file (`applyStamps`);
 * scripts/stamp-wire-contract.ts only reads, writes and reports.
 *
 * The wire-contract start marker still names agents/_shared/, where the
 * fragment lived before it moved: the byte-frozen schema-1 archive
 * (references/reviewer-protocol-v1/) carries that exact marker and is read
 * through this same extraction, so the spelling cannot change.
 */

export const WIRE_CONTRACT_START =
  "<!-- wire-contract:start — stamped from agents/_shared/wire-contract.md; edit the fragment, then run scripts/stamp-wire-contract.ts -->";
export const WIRE_CONTRACT_END = "<!-- wire-contract:end -->";

export type StampResult =
  | Readonly<{ ok: true; value: string }>
  | Readonly<{ ok: false; error: string }>;

/** One marker-delimited region of an agent file, owned whole by one fragment. */
export type StampedRegion = Readonly<{ name: string; start: string; end: string }>;

export const WIRE_CONTRACT_REGION: StampedRegion = Object.freeze({
  name: "wire-contract",
  start: WIRE_CONTRACT_START,
  end: WIRE_CONTRACT_END,
});

/** The Context Packet bootstrap every reviewer opens with (references/reviewer-wire/bootstrap.md). */
export const REVIEWER_BOOTSTRAP_REGION: StampedRegion = Object.freeze({
  name: "reviewer-bootstrap",
  start: "<!-- reviewer-bootstrap:start — stamped from references/reviewer-wire/bootstrap.md -->",
  end: "<!-- reviewer-bootstrap:end -->",
});

/** The payload preflight every reviewer runs before emitting (references/reviewer-wire/before-you-emit.md). */
export const REVIEWER_PREFLIGHT_REGION: StampedRegion = Object.freeze({
  name: "reviewer-preflight",
  start: "<!-- reviewer-preflight:start — stamped from references/reviewer-wire/before-you-emit.md -->",
  end: "<!-- reviewer-preflight:end -->",
});

/** The refutation lens definitions the verifier carries (references/review-lenses.md). */
export const REVIEW_LENSES_REGION: StampedRegion = Object.freeze({
  name: "review-lenses",
  start: "<!-- review-lenses:start — stamped from references/review-lenses.md -->",
  end: "<!-- review-lenses:end -->",
});

/**
 * The lens sections of references/review-lenses.md as the verifier carries
 * them: from the first `## <lens>` heading to the end of the file, every
 * heading demoted one level so the sections nest under the agent's
 * `## Lenses`. The file's header (selection order, table, standing rule) is
 * for maintainers and is not stamped.
 *
 * Refuses a reference whose sections from there on are not exactly `lenses`
 * in order: the verifier is issued its lens by name, so a selectable lens
 * with no section, or a section no lens selects, must stop the stamp.
 */
export function reviewLensSections(reference: string, lenses: readonly string[]): StampResult {
  const lines = reference.split("\n");
  const first = lines.findIndex((line) => lenses.some((lens) => line === `## ${lens}`));
  if (first === -1) return { ok: false, error: "lens reference has no `## <lens>` section" };
  const sections = lines.slice(first);
  const documented = sections.filter((line) => line.startsWith("## ")).map((line) => line.slice(3));
  if (documented.join("\n") !== lenses.join("\n")) {
    return {
      ok: false,
      error: `lens reference sections [${documented.join(", ")}] are not the selectable lenses [${lenses.join(", ")}]`,
    };
  }
  return { ok: true, value: sections.map((line) => /^#+ /.test(line) ? `#${line}` : line).join("\n") };
}

type RegionBounds =
  | Readonly<{ ok: true; start: number; end: number }>
  | Readonly<{ ok: false; error: string }>;

/** Where a region's markers sit, or an error naming which one is missing. */
function regionBounds(agentMarkdown: string, region: StampedRegion): RegionBounds {
  const start = agentMarkdown.indexOf(region.start);
  const end = agentMarkdown.indexOf(region.end);
  if (start === -1) return { ok: false, error: `missing ${region.name} start marker` };
  if (end === -1) return { ok: false, error: `missing ${region.name} end marker` };
  if (end < start) return { ok: false, error: `${region.name} markers are out of order` };
  return { ok: true, start, end };
}

/** Extract a region's current content, or an error naming what's missing. */
export function extractRegion(agentMarkdown: string, region: StampedRegion): StampResult {
  const bounds = regionBounds(agentMarkdown, region);
  if (!bounds.ok) return bounds;
  const inner = agentMarkdown.slice(bounds.start + region.start.length, bounds.end);
  return { ok: true, value: inner.replace(/^\n/, "").replace(/\n$/, "") };
}

/** Replace a region with its fragment, byte-exact and idempotent. */
export function stampRegion(agentMarkdown: string, region: StampedRegion, fragment: string): StampResult {
  const bounds = regionBounds(agentMarkdown, region);
  if (!bounds.ok) return bounds;
  return {
    ok: true,
    value:
      agentMarkdown.slice(0, bounds.start + region.start.length) +
      "\n" + fragment.replace(/\n$/, "") + "\n" +
      agentMarkdown.slice(bounds.end),
  };
}

/** Extract the stamped wire-contract region's current content. */
export const extractWireContractRegion = (agentMarkdown: string): StampResult =>
  extractRegion(agentMarkdown, WIRE_CONTRACT_REGION);

/** Replace the stamped wire-contract region with the fragment. */
export const stampWireContract = (agentMarkdown: string, fragment: string): StampResult =>
  stampRegion(agentMarkdown, WIRE_CONTRACT_REGION, fragment);

/** The opening words that locate the read-coverage bullet in a reviewer file. */
export const READ_COVERAGE_BULLET_ANCHOR = "- When the engine task carries `LOOM_READ_COVERAGE: ";

/** The one line starting with the read-coverage anchor, or an error naming why there is not exactly one. */
export function extractReadCoverageBullet(agentMarkdown: string): StampResult {
  const bullets = agentMarkdown.split("\n").filter((line) => line.startsWith(READ_COVERAGE_BULLET_ANCHOR));
  if (bullets.length === 0) return { ok: false, error: "missing read-coverage bullet" };
  if (bullets.length > 1) return { ok: false, error: `${bullets.length} read-coverage bullets; expected exactly one` };
  return { ok: true, value: bullets[0]! };
}

/** Replace the read-coverage bullet with the one-line fragment, byte-exact and idempotent. */
export function stampReadCoverageBullet(agentMarkdown: string, fragment: string): StampResult {
  const bullet = fragment.replace(/\n$/, "");
  if (!bullet.startsWith(READ_COVERAGE_BULLET_ANCHOR) || bullet.includes("\n")) {
    return { ok: false, error: "read-coverage fragment must be one line starting with its anchor" };
  }
  const current = extractReadCoverageBullet(agentMarkdown);
  if (!current.ok) return current;
  return {
    ok: true,
    value: agentMarkdown.split("\n").map((line) => line === current.value ? bullet : line).join("\n"),
  };
}

/** Where the reviewer fragments live, and the reference the verifier's lens region is cut from. */
export const REVIEWER_WIRE_FRAGMENTS = "references/reviewer-wire";
export const REVIEW_LENS_REFERENCE = "references/review-lenses.md";

/**
 * The text an agent of one kind is stamped from. The kinds are the Agent
 * Catalog's: an agent of any other kind carries no stamped text.
 */
export type StampSources =
  | Readonly<{
      kind: "reviewer";
      /** references/reviewer-wire/bootstrap.md */
      bootstrap: string;
      /** references/reviewer-wire/before-you-emit.md */
      preflight: string;
      /** The executable contract, as renderReviewerWireContract() prints it. */
      wireContract: string;
      /** references/reviewer-wire/read-coverage.md */
      readCoverage: string;
    }>
  | Readonly<{
      kind: "review-verifier";
      /** `reviewLensSections` of references/review-lenses.md. */
      lensSections: string;
    }>;

/** One source's replacement in an agent file, with the words that report it. */
export type Stamp = Readonly<{
  apply: (agentMarkdown: string) => StampResult;
  /** What a refused stamp should have found in the file. */
  expected: string;
  /** What a drift check reports when the file differs. */
  difference: string;
}>;

const regionStamp = (region: StampedRegion, source: string, text: string): Stamp => ({
  apply: (agentMarkdown) => stampRegion(agentMarkdown, region, text),
  expected: `${region.start} … ${region.end}`,
  difference: `${region.name} region differs from ${source}`,
});

/** Every stamp an agent of the sources' kind carries, in file order. */
export function stampsFor(sources: StampSources): readonly Stamp[] {
  switch (sources.kind) {
    case "reviewer":
      return [
        regionStamp(REVIEWER_BOOTSTRAP_REGION, `${REVIEWER_WIRE_FRAGMENTS}/bootstrap.md`, sources.bootstrap),
        regionStamp(REVIEWER_PREFLIGHT_REGION, `${REVIEWER_WIRE_FRAGMENTS}/before-you-emit.md`, sources.preflight),
        regionStamp(WIRE_CONTRACT_REGION, `${REVIEWER_WIRE_FRAGMENTS}/wire-contract.md`, sources.wireContract),
        {
          apply: (agentMarkdown) => stampReadCoverageBullet(agentMarkdown, sources.readCoverage),
          expected: `one line starting ${READ_COVERAGE_BULLET_ANCHOR}`,
          difference: `read-coverage bullet differs from ${REVIEWER_WIRE_FRAGMENTS}/read-coverage.md`,
        },
      ];
    case "review-verifier":
      return [regionStamp(REVIEW_LENSES_REGION, REVIEW_LENS_REFERENCE, sources.lensSections)];
    default: {
      const unreachable: never = sources;
      return unreachable;
    }
  }
}

/** A stamp the file could not take: why, and what it should have held. */
export type StampRefusal = Readonly<{ reason: string; expected: string }>;

/**
 * One agent file after every stamp: its stamped text and the `difference` of
 * each stamp that changed it (none when the file was already current), or the
 * first stamp the file refused.
 */
export type StampedAgentFile =
  | Readonly<{ ok: true; value: string; differing: readonly string[] }>
  | Readonly<{ ok: false; error: StampRefusal }>;

/** Apply the stamps in order, each to the result of the one before. */
export function applyStamps(agentMarkdown: string, stamps: readonly Stamp[]): StampedAgentFile {
  return stamps.reduce<StampedAgentFile>(
    (file, { apply, expected, difference }) => {
      if (!file.ok) return file;
      const next = apply(file.value);
      if (!next.ok) return { ok: false, error: { reason: next.error, expected } };
      return {
        ok: true,
        value: next.value,
        differing: next.value === file.value ? file.differing : [...file.differing, difference],
      };
    },
    { ok: true, value: agentMarkdown, differing: [] },
  );
}
